  toks = tokenizer$tokenize(text)
  fastai2$vision$all$tensor(tokenizer$convert_tokens_to_ids(toks))
}

TransformersTokenizer <- reticulate::PyClass(
  'TransformersTokenizer',
  inherit = fastai2$text$all$Transform,
  list(
    `__init__` = function(self, tokenizer) {
      self$tokenizer <- tokenizer
      NULL
    },

    encodes = function(self, x) {
      if(inherits(x,"torch.Tensor")) {
        x
      } else {
        tokenize(x)
      }
    },

    decodes = function(self, x) {
      self$tokenizer$decode(x$cpu()$numpy())
    }
  )
)

